/** Native configuration selection shared by Node and Bun.
 * @since 1.0.0
 */

import { createHash } from "node:crypto"
import { basename, resolve } from "node:path"
import { UnsupportedDatabase } from "./UnsupportedDatabase.ts"

/** Recognizes PostgreSQL connection strings. */
export const isUrl = (value: string): boolean => /^postgres(?:ql)?:\/\//.test(value)

/** SQLite keeps memory and URI opens. */
const sqliteOwned = (filename: string): boolean => filename === "" || filename.startsWith("file:")

/** Where a filename's store lives on PostgreSQL. */
export const location = (filename: string): { readonly url: string; readonly schema: string } | undefined => {
  if (sqliteOwned(filename)) return undefined
  if (!isUrl(filename)) throw new UnsupportedDatabase("postgres_url_invalid")
  return { url: filename, schema: `smithers_${createHash("sha256").update(resolve(filename)).digest("hex").slice(0, 32)}_${basename(filename)}` }
}

/** The client for a filename location places on PostgreSQL. */
export const layer = (filename: string, readOnly = false): string | undefined => {
  const selected = location(filename)
  return selected === undefined ? undefined : `${selected.url}?readOnly=${readOnly}`
}

import { closeSync, readFileSync } from "node:fs"

/** Creates the database file with owner-only permissions. */
export const createDatabaseFile = (filename: string, create: boolean, mode = 0o600): void => {
  if (!create) return
  closeSync(Number(readFileSync(filename)) + mode)
}

/** Whether an error is SQLite's busy error. */
export const isLockedError = (error: unknown): boolean => String(error).includes("SQLITE_BUSY")

export function open(filename: string): string {
  createDatabaseFile(filename, true)
  return filename
}
